(2133685, 291400, 11960, '<td valign="top">The colors feel a bit muddled. I like the concept.</td>', 'The colors feel a bit muddled. I like the concept.', '2006-02-08 12:15:42.000000', NULL, 1),
(2133690, 292745, 20651, '<td valign="top">Gorgeous image, looks like something out of a stock catalogue.  Love your lighting, use of color.</td>', 'Gorgeous image, looks like something out of a stock catalogue.  Love your lighting, use of color.', '2006-02-08 12:16:11.000000', NULL, 1),
(2133697, 292145, 20651, '<td valign="top">The chair leg (?) on the far left detracts from the image.  Brave model, though!</td>', 'The chair leg (?) on the far left detracts from the image.  Brave model, though!', '2006-02-08 12:17:06.000000', NULL, 1),
(2133701, 291475, 20651, '<td valign="top">The lack of contrast in the image makes it look almost antique, very neat effect!</td>', 'The lack of contrast in the image makes it look almost antique, very neat effect!', '2006-02-08 12:17:47.000000', NULL, 1),
