INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2136264, 292187, 10858, '<td valign="top">Composition is quite good, but I am not familiar with the quality. Overexposion is distracting on the pilot''s face, but even makes the whole shot quite unnatural.</td>', 'Composition is quite good, but I am not familiar with the quality. Overexposion is distracting on the pilot''s face, but even makes the whole shot quite unnatural.', '2006-02-09 07:32:10.000000', NULL, 1),
(2136269, 292868, 10858, '<td valign="top">Nice idea, though, quality should be better, and somehow the photo lacks the colours. My compact does similar when I take the shot in weak natural lights.</td>', 'Nice idea, though, quality should be better, and somehow the photo lacks the colours. My compact does similar when I take the shot in weak natural lights.', '2006-02-09 07:34:11.000000', NULL, 1),
(2136270, 292832, 10858, '<td valign="top">This shot would be more interesting from a lower angle. Also needs more lights, and more diffused lights to avoid the darkness mixed with blow outs and the out of focus effect.</td>', 'This shot would be more interesting from a lower angle. Also needs more lights, and more diffused lights to avoid the darkness mixed with blow outs and the out of focus effect.', '2006-02-09 07:35:19.000000', NULL, 1),
