(2137278, 291771, 50551, '<td valign="top">A very amusing shot - almost the Monarch of the Glen! Love the contrast of the gravy boat with the oven too.</td>', 'A very amusing shot - almost the Monarch of the Glen! Love the contrast of the gravy boat with the oven too.', '2006-02-09 15:42:39.000000', NULL, 1),
