(2139916, 292772, 33732, '<td valign="top">Unrealistic support for teh doll.</td>', 'Unrealistic support for teh doll.', '2006-02-10 10:45:04.000000', NULL, 1),
(2139917, 292200, 31541, '<td valign="top">Hi.  Great barn.  I think that getting a little closer would help.  The tree in the foreground is kind of distracting.  Also, I think this could use a little more contrast (looks a little flat).</td>', 'Hi.  Great barn.  I think that getting a little closer would help.  The tree in the foreground is kind of distracting.  Also, I think this could use a little more contrast (looks a little flat).', '2006-02-10 10:45:06.000000', NULL, 1),
