(2141706, 292830, 52843, '<td valign="top">I laughed so hard when I saw this! Excellent photo, the cat''s eyes are at the right level, the scene is nicely "arranged", and the feel of the photo fits the challenge criteria very well. Very creative - Purrfect!</td>', 'I laughed so hard when I saw this! Excellent photo, the cat''s eyes are at the right level, the scene is nicely "arranged", and the feel of the photo fits the challenge criteria very well. Very creative - Purrfect!', '2006-02-11 00:07:22.000000', NULL, 1),
(2141719, 292189, 18799, '<td valign="top">I like this subject, but can''t decide if I like the scratches.   I''m thinking it was intentional, and I''m probably being a bit daft for not seeing the connection to the subject.  The b/w is good.  There is a bit of a hot spot on the left side, but it''s not a killer for me (try a shot of hair spray to kill reflections).   7</td>', 'I like this subject, but can''t decide if I like the scratches.   I''m thinking it was intentional, and I''m probably being a bit daft for not seeing the connection to the subject.  The b/w is good.  There is a bit of a hot spot on the left side, but it''s not a killer for me (try a shot of hair spray to kill reflections).   7', '2006-02-11 00:13:31.000000', NULL, 1),
(2141727, 290818, 18799, '<td valign="top">The image is very good.  I don''t know what the title means.  I don''t see broken in the picture.</td>', 'The image is very good.  I don''t know what the title means.  I don''t see broken in the picture.', '2006-02-11 00:15:12.000000', NULL, 1),
(2141738, 291980, 18799, '<td valign="top">I think the harsh lighting due to the mid-day sun hurt this picture.  The subject is good, and definately meets the challenge.  I think you should go back and get a late afternoon, or early morning shot for comparison purposes. 6</td>', 'I think the harsh lighting due to the mid-day sun hurt this picture.  The subject is good, and definately meets the challenge.  I think you should go back and get a late afternoon, or early morning shot for comparison purposes. 6', '2006-02-11 00:17:54.000000', NULL, 1),
(2141748, 290159, 52843, '<td valign="top">I like this. Nice atmosphere and contrast of sharpness between the building and clouds.</td>', 'I like this. Nice atmosphere and contrast of sharpness between the building and clouds.', '2006-02-11 00:18:45.000000', NULL, 1),
(2141750, 292091, 18799, '<td valign="top">Very nicely captured.  The backlight is great.   10</td>', 'Very nicely captured.  The backlight is great.   10', '2006-02-11 00:19:01.000000', NULL, 1),
(2141759, 291172, 18799, '<td valign="top">Great job of capturing an unusual perspective.  8</td>', 'Great job of capturing an unusual perspective.  8', '2006-02-11 00:20:06.000000', NULL, 1),
(2141763, 292745, 52843, '<td valign="top">Very pleasing image. :)</td>', 'Very pleasing image. :)', '2006-02-11 00:20:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2141781, 292745, 18799, '<td valign="top">I like the geometric shapes created by piling the broken pieces on top of one another.  The backlight nicely separate the subject and dthe red liquid is just enough to add interest but not overpower the image.  Great job.  10</td>', 'I like the geometric shapes created by piling the broken pieces on top of one another.  The backlight nicely separate the subject and dthe red liquid is just enough to add interest but not overpower the image.  Great job.  10', '2006-02-11 00:23:50.000000', NULL, 1),
(2141785, 290159, 46993, '<td valign="top">10,10,10.  In my opinion.  I like the framing, the contrast,and the B &amp; W imaging.  Super job!</td>', '10,10,10.  In my opinion.  I like the framing, the contrast,and the B & W imaging.  Super job!', '2006-02-11 00:24:25.000000', NULL, 1),
