(2143984, 289810, 20956, '<td valign="top">dark and out of focus</td>', 'dark and out of focus', '2006-02-12 03:56:48.000000', NULL, 1),
(2144102, 292091, 36382, '<td valign="top">Gosh you have put my entry to shame.  Great sense of movement.  It seems ever so slightly dark on my monitor, but maybe that was your intention.  Either way I had to give 10.</td>', 'Gosh you have put my entry to shame.  Great sense of movement.  It seems ever so slightly dark on my monitor, but maybe that was your intention.  Either way I had to give 10.', '2006-02-12 08:14:43.000000', NULL, 1),
(2144103, 292805, 36382, '<td valign="top">Good aspect.  Nice post-processing too.</td>', 'Good aspect.  Nice post-processing too.', '2006-02-12 08:15:11.000000', NULL, 1),
(2144104, 292830, 36382, '<td valign="top">Amazing what an actor.  I wonder how many outtakes!</td>', 'Amazing what an actor.  I wonder how many outtakes!', '2006-02-12 08:15:18.000000', NULL, 1),
(2144105, 292151, 36382, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2006-02-12 08:15:24.000000', NULL, 1),
(2144106, 292855, 36382, '<td valign="top">Super crisp and good play with the word ''perfect''. 8.</td>', 'Super crisp and good play with the word ''perfect''. 8.', '2006-02-12 08:15:38.000000', NULL, 1),
(2144107, 290688, 36382, '<td valign="top">Recognisable style.  Very good. 8</td>', 'Recognisable style.  Very good. 8', '2006-02-12 08:15:53.000000', NULL, 1),
(2144109, 292022, 36382, '<td valign="top">Nice take on familiar idea. 8</td>', 'Nice take on familiar idea. 8', '2006-02-12 08:16:24.000000', NULL, 1),
(2144110, 291205, 36382, '<td valign="top">I really like this shot.  The blue seat really stands out from the brown bike.  I think it could be even better IMO if you took a little bit off the rh side and then also the top, so that some of the out of focus areas are there but less of them.</td>', 'I really like this shot.  The blue seat really stands out from the brown bike.  I think it could be even better IMO if you took a little bit off the rh side and then also the top, so that some of the out of focus areas are there but less of them.', '2006-02-12 08:16:58.000000', NULL, 1),
(2144111, 292443, 36382, '<td valign="top">Nice contrasts.</td>', 'Nice contrasts.', '2006-02-12 08:17:34.000000', NULL, 1),
(2144112, 290599, 36382, '<td valign="top">Ooo creepy.  Nice lighting.  Should make top ten, I think.</td>', 'Ooo creepy.  Nice lighting.  Should make top ten, I think.', '2006-02-12 08:17:41.000000', NULL, 1),
(2144113, 289943, 36382, '<td valign="top">One of my top picks.  Lovely lighting.  The dust looks good. (Never thought I''d ever say that)</td>', 'One of my top picks.  Lovely lighting.  The dust looks good. (Never thought I''d ever say that)', '2006-02-12 08:17:49.000000', NULL, 1),
(2144117, 292189, 36382, '<td valign="top">Different and the black and white works well here. 8.</td>', 'Different and the black and white works well here. 8.', '2006-02-12 08:18:59.000000', NULL, 1),
(2144140, 290047, 52343, '<td valign="top">Good concept, good positioning and angle, nice lighting, however be more thoughtful of the backdrop material you choose, it''s color works well with the subject but the wooly boogers in the forground are distracting.</td>', 'Good concept, good positioning and angle, nice lighting, however be more thoughtful of the backdrop material you choose, it''s color works well with the subject but the wooly boogers in the forground are distracting.', '2006-02-12 09:00:52.000000', NULL, 1),
(2144144, 291872, 44611, '<td valign="top">Super macro - meets the challenge perfectly.  Deserves a good place.</td>', 'Super macro - meets the challenge perfectly.  Deserves a good place.', '2006-02-12 09:07:53.000000', NULL, 1),
(2144145, 291205, 44611, '<td valign="top">Great close up and good subject matter.</td>', 'Great close up and good subject matter.', '2006-02-12 09:08:27.000000', NULL, 1),
(2144146, 292595, 52343, '<td valign="top">pretty cool...did you try cocking the wrist to make it look like the hand was dangling by a piece of flesh?</td>', 'pretty cool...did you try cocking the wrist to make it look like the hand was dangling by a piece of flesh?', '2006-02-12 09:08:37.000000', NULL, 1),
(2144150, 292813, 44611, '<td valign="top">Best broken egg shot in the challenge, even if it doesn''t quite meet the ''find something already broken'' bit!  Clever work.</td>', 'Best broken egg shot in the challenge, even if it doesn''t quite meet the ''find something already broken'' bit!  Clever work.', '2006-02-12 09:11:04.000000', NULL, 1),
(2144151, 290047, 47852, '<td valign="top">The way the sneakers are positioned is pleasing, but the background sheet seems unnatural.  The darkness of the shot works for a broken challenge, but then again.. what about these sneakers is broken?</td>', 'The way the sneakers are positioned is pleasing, but the background sheet seems unnatural.  The darkness of the shot works for a broken challenge, but then again.. what about these sneakers is broken?', '2006-02-12 09:11:18.000000', NULL, 1),
(2144153, 291998, 44611, '<td valign="top">Great shot - deserves a ribbon in my book.</td>', 'Great shot - deserves a ribbon in my book.', '2006-02-12 09:12:34.000000', NULL, 1),
(2144155, 292723, 44611, '<td valign="top">This meets the challenge well, but lacks any real point of interest.  You would have done better, I think, had you focused specifically on one of the broken windows for example.</td>', 'This meets the challenge well, but lacks any real point of interest.  You would have done better, I think, had you focused specifically on one of the broken windows for example.', '2006-02-12 09:14:08.000000', NULL, 1),
(2144158, 292361, 44611, '<td valign="top">I can''t make out anything specifically broken as the focus is a bit soft and the image quite small.  Try to make your submission larger (you can use up to 640 pixels) and at least one part of the image in sharp focus.</td>', 'I can''t make out anything specifically broken as the focus is a bit soft and the image quite small.  Try to make your submission larger (you can use up to 640 pixels) and at least one part of the image in sharp focus.', '2006-02-12 09:15:21.000000', NULL, 1),
(2144160, 292610, 44611, '<td valign="top">Meets the challenge well, but the lighting is so depressing this loses any impact it may have through dimness.</td>', 'Meets the challenge well, but the lighting is so depressing this loses any impact it may have through dimness.', '2006-02-12 09:16:13.000000', NULL, 1),
(2144161, 290517, 44611, '<td valign="top">Broken - mmmm - well, I guess they are in a sense, but it''s pushing it as a definition.  Also the focus is very soft on this - should be sharper.</td>', 'Broken - mmmm - well, I guess they are in a sense, but it''s pushing it as a definition.  Also the focus is very soft on this - should be sharper.', '2006-02-12 09:17:02.000000', NULL, 1),
(2144163, 290698, 44611, '<td valign="top">This image is rather small - you should try to use the whole 640 pixel size allowance for your submission.  Secondly the broken subject is rather lost amongst the rest of the image.  Closer focus on the torn cover would have helped.</td>', 'This image is rather small - you should try to use the whole 640 pixel size allowance for your submission.  Secondly the broken subject is rather lost amongst the rest of the image.  Closer focus on the torn cover would have helped.', '2006-02-12 09:19:24.000000', NULL, 1),
(2144165, 292317, 44611, '<td valign="top">Shame about the odd angle, and it''s not entirely clear that this van is broken or broken down.  This was a great possible subject, but you needed to focus more on an obviously broken bit.</td>', 'Shame about the odd angle, and it''s not entirely clear that this van is broken or broken down.  This was a great possible subject, but you needed to focus more on an obviously broken bit.', '2006-02-12 09:21:24.000000', NULL, 1),
(2144166, 292610, 47852, '<td valign="top">Nice composition and a catchy title... unfortunately the shot is a bit dark for me.</td>', 'Nice composition and a catchy title... unfortunately the shot is a bit dark for me.', '2006-02-12 09:21:26.000000', NULL, 1),
(2144168, 291161, 44611, '<td valign="top">Sorry, but with those heads in the background, this can only come across as a poorly composed and rather rushed snapshot.  The subject was a good one which fitted the challenge, although I can imagine not easy to take a picture of.  In future, though, at least wait until you can get a clear shot.</td>', 'Sorry, but with those heads in the background, this can only come across as a poorly composed and rather rushed snapshot.  The subject was a good one which fitted the challenge, although I can imagine not easy to take a picture of.  In future, though, at least wait until you can get a clear shot.', '2006-02-12 09:23:57.000000', NULL, 1),
(2144170, 289442, 44611, '<td valign="top">Too small - I won''t be the only one to tell you.</td>', 'Too small - I won''t be the only one to tell you.', '2006-02-12 09:24:34.000000', NULL, 1),
(2144172, 292548, 44611, '<td valign="top">Sorry but the focus is far too soft on this entry and there is poor definition in the edges and shadows.</td>', 'Sorry but the focus is far too soft on this entry and there is poor definition in the edges and shadows.', '2006-02-12 09:25:44.000000', NULL, 1),
(2144173, 292255, 44611, '<td valign="top">If only this had been a larger submission then it may have scored much better.</td>', 'If only this had been a larger submission then it may have scored much better.', '2006-02-12 09:26:12.000000', NULL, 1),
(2144176, 290413, 44611, '<td valign="top">Broken - definitely.  Composition and focus are fair.  An interesting or appealing image - no, I''m sorry not at all.</td>', 'Broken - definitely.  Composition and focus are fair.  An interesting or appealing image - no, I''m sorry not at all.', '2006-02-12 09:27:34.000000', NULL, 1),
(2144177, 291162, 44611, '<td valign="top">Focus is rather soft which makes it hard to make out the subject matter distinctly.</td>', 'Focus is rather soft which makes it hard to make out the subject matter distinctly.', '2006-02-12 09:28:46.000000', NULL, 1),
(2144190, 292712, 47852, '<td valign="top">Its like looking at a slightly crooked picture frame on a wall... I want to nudge the corner a bit to straighten it out.  It''s a neat shot though.</td>', 'Its like looking at a slightly crooked picture frame on a wall... I want to nudge the corner a bit to straighten it out.  It''s a neat shot though.', '2006-02-12 09:39:07.000000', NULL, 1),
(2144204, 291899, 47852, '<td valign="top">Interesting shapes in the broken windows.  Some of them look like silhouettes of faces or characters.  Neat shot!</td>', 'Interesting shapes in the broken windows.  Some of them look like silhouettes of faces or characters.  Neat shot!', '2006-02-12 09:44:13.000000', NULL, 1),
(2144205, 290160, 47852, '<td valign="top">Interesting lines created by these walls of stone as well as a nice color variation.  All grey would have been too bland.  A nice angle you used to capture them.</td>', 'Interesting lines created by these walls of stone as well as a nice color variation.  All grey would have been too bland.  A nice angle you used to capture them.', '2006-02-12 09:44:18.000000', NULL, 1),
(2144206, 292830, 47852, '<td valign="top">I like the story this one tells instead of just looking at a picture of a broken object.</td>', 'I like the story this one tells instead of just looking at a picture of a broken object.', '2006-02-12 09:44:45.000000', NULL, 1),
(2144207, 291240, 47852, '<td valign="top">Great use of dof to focus the viewer in on the letter/rings, but perhaps just a bit more lighting on the letter would help too.</td>', 'Great use of dof to focus the viewer in on the letter/rings, but perhaps just a bit more lighting on the letter would help too.', '2006-02-12 09:45:18.000000', NULL, 1),
(2144208, 292636, 47852, '<td valign="top">Neat shot... works as an abstract too!</td>', 'Neat shot... works as an abstract too!', '2006-02-12 09:45:24.000000', NULL, 1),
(2144210, 291805, 47852, '<td valign="top">Unique angle... I like the long drips.</td>', 'Unique angle... I like the long drips.', '2006-02-12 09:45:45.000000', NULL, 1),
(2144268, 289836, 47852, '<td valign="top">What an interesting illusion here... creative and well done!  One of my top picks for this challenge!</td>', 'What an interesting illusion here... creative and well done!  One of my top picks for this challenge!', '2006-02-12 10:19:52.000000', NULL, 1),
(2144272, 292611, 47852, '<td valign="top">I have no idea what this is a part of.. but it definately has a broken feel to it.  Simple and unique with nice tones and good focus.  One of my top picks from the challenge.</td>', 'I have no idea what this is a part of.. but it definately has a broken feel to it.  Simple and unique with nice tones and good focus.  One of my top picks from the challenge.', '2006-02-12 10:22:02.000000', NULL, 1),
(2144273, 292540, 52296, '<td valign="top">Nice, maybe a little more contrast??</td>', 'Nice, maybe a little more contrast??', '2006-02-12 10:23:25.000000', NULL, 1),
(2144347, 292772, 35545, '<td valign="top">Double whammy -- the doll and the window.  Focus could be a little sharper, but this meets the challenge and then some.</td>', 'Double whammy -- the doll and the window.  Focus could be a little sharper, but this meets the challenge and then some.', '2006-02-12 11:44:22.000000', NULL, 1),
(2144349, 292031, 35545, '<td valign="top">Picture goes soft on the sides.</td>', 'Picture goes soft on the sides.', '2006-02-12 11:44:52.000000', NULL, 1),
(2144350, 292613, 35545, '<td valign="top">I really like the use of b&amp;w, but I think this would be better in the Abstract Challenge.  What am I looking at?</td>', 'I really like the use of b&w, but I think this would be better in the Abstract Challenge.  What am I looking at?', '2006-02-12 11:45:43.000000', NULL, 1),
(2144352, 292074, 35545, '<td valign="top">A broken neck?  Ugh!</td>', 'A broken neck?  Ugh!', '2006-02-12 11:46:57.000000', NULL, 1),
(2144357, 292026, 35545, '<td valign="top">I figured out that those are broken eggs (good idea), but they need a little more shadow on the inside.  On my monitor, they come across as white spaces.  5</td>', 'I figured out that those are broken eggs (good idea), but they need a little more shadow on the inside.  On my monitor, they come across as white spaces.  5', '2006-02-12 11:48:56.000000', NULL, 1),
(2144358, 292112, 35545, '<td valign="top">Unappealing.</td>', 'Unappealing.', '2006-02-12 11:50:42.000000', NULL, 1),
(2144362, 290897, 35545, '<td valign="top">Do you mean "wraith" or "wrath"?</td>', 'Do you mean "wraith" or "wrath"?', '2006-02-12 11:53:00.000000', NULL, 1),
(2144373, 290047, 35545, '<td valign="top">I''ve looked at this picture several times, and I just can''t get broken out of it.  It is an absolutely beautiful picture of an old, dirty pair of sneakers. 6 and to hell with the DNMC nazis.</td>', 'I''ve looked at this picture several times, and I just can''t get broken out of it.  It is an absolutely beautiful picture of an old, dirty pair of sneakers. 6 and to hell with the DNMC nazis.', '2006-02-12 11:58:21.000000', NULL, 1),
(2144518, 291996, 16241, '<td valign="top">good idea, good photo.</td>', 'good idea, good photo.', '2006-02-12 14:16:25.000000', NULL, 1),
