(2144525, 291805, 16241, '<td valign="top">good</td>', 'good', '2006-02-12 14:19:50.000000', NULL, 1),
(2144539, 292597, 53247, '<td valign="top">This is a neat idea!</td>', 'This is a neat idea!', '2006-02-12 14:29:14.000000', NULL, 1),
