(2144604, 292816, 51889, '<td valign="top">Nice pout :) I love the focus on his eye.</td>', 'Nice pout :) I love the focus on his eye.', '2006-02-12 15:05:06.000000', NULL, 1),
(2144606, 292558, 51889, '<td valign="top">The whole color scheme works great. Excellent cropping.</td>', 'The whole color scheme works great. Excellent cropping.', '2006-02-12 15:05:45.000000', NULL, 1),
