(2144722, 291872, 28963, '<td valign="top">Very nice composition. I wish you could have gotten rid of the shadows, either with the lighting og by dodging. Anyways great shot.</td>', 'Very nice composition. I wish you could have gotten rid of the shadows, either with the lighting og by dodging. Anyways great shot.', '2006-02-12 16:20:02.000000', NULL, 1),
(2144723, 292597, 28963, '<td valign="top">Awesome. 2 of my favourite things, PDA''s and x-rays. Very cool idea and great execution.</td>', 'Awesome. 2 of my favourite things, PDA''s and x-rays. Very cool idea and great execution.', '2006-02-12 16:20:41.000000', NULL, 1),
(2144724, 292151, 28963, '<td valign="top">Fantastic, Great composition IMO. Love the look of the water. On my screen it''s a bit too bright, I think a darker tone would have helped transfer the feeling of degeneration and aging better. Bump anyways.</td>', 'Fantastic, Great composition IMO. Love the look of the water. On my screen it''s a bit too bright, I think a darker tone would have helped transfer the feeling of degeneration and aging better. Bump anyways.', '2006-02-12 16:20:45.000000', NULL, 1),
(2144725, 291693, 28963, '<td valign="top">Great, great shot.</td>', 'Great, great shot.', '2006-02-12 16:20:55.000000', NULL, 1),
(2144726, 292747, 53247, '<td valign="top">those are some funky glasses lol.</td>', 'those are some funky glasses lol.', '2006-02-12 16:20:59.000000', NULL, 1),
(2144727, 292640, 28963, '<td valign="top">Great catch, how did you time this? My only problems (small ones) are that I find it a little overexposed and I think I would like it better if the bulb would have been a little lower in the frame and one saw more of the hammer. Good job!</td>', 'Great catch, how did you time this? My only problems (small ones) are that I find it a little overexposed and I think I would like it better if the bulb would have been a little lower in the frame and one saw more of the hammer. Good job!', '2006-02-12 16:21:04.000000', NULL, 1),
