(2145253, 289943, 48228, '<td valign="top">This has been well thought out, and also taken really well. I think you should be very happy with this image, as I also give it the "WOW" factor..... I really love the dusty/dirty appearance, as it gives it an ageing quality.</td>', 'This has been well thought out, and also taken really well. I think you should be very happy with this image, as I also give it the "WOW" factor..... I really love the dusty/dirty appearance, as it gives it an ageing quality.', '2006-02-12 20:35:21.000000', NULL, 1),
(2145254, 292443, 48228, '<td valign="top">Excellent subject matter, and a really good image as well.....I really love this simple, to the point B/W image, and I have one word to say, yes, "WOW".....One of my favorites in this challenge.</td>', 'Excellent subject matter, and a really good image as well.....I really love this simple, to the point B/W image, and I have one word to say, yes, "WOW".....One of my favorites in this challenge.', '2006-02-12 20:35:28.000000', NULL, 1),
