(2149472, 292805, 50695, '<td valign="top">The alignment of truck in truck window is perfect, and the colors are great.</td>', 'The alignment of truck in truck window is perfect, and the colors are great.', '2006-02-14 08:54:03.000000', NULL, 1),
(2149478, 292321, 50695, '<td valign="top">What makes this picture for me is the way the spots of decay and paint blend in with the leaves.</td>', 'What makes this picture for me is the way the spots of decay and paint blend in with the leaves.', '2006-02-14 08:55:05.000000', NULL, 1),
