INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2149494, 292321, 48298, '<td valign="top">Cool colors.  Looks like you softened it a bit, which is within the rules and looks good.  9.</td>', 'Cool colors.  Looks like you softened it a bit, which is within the rules and looks good.  9.', '2006-02-14 09:00:26.000000', NULL, 1),
(2149503, 292610, 48298, '<td valign="top">I like the idea, but it''s a little too dark and the focus isn''t sharp.</td>', 'I like the idea, but it''s a little too dark and the focus isn''t sharp.', '2006-02-14 09:04:01.000000', NULL, 1),
(2149504, 292184, 48298, '<td valign="top">Nice and simple.</td>', 'Nice and simple.', '2006-02-14 09:04:54.000000', NULL, 1),
(2149508, 289943, 48298, '<td valign="top">Very interesting to look at.  I like all the broken pieces...maybe could have put a crack in the centered bottle, too?</td>', 'Very interesting to look at.  I like all the broken pieces...maybe could have put a crack in the centered bottle, too?', '2006-02-14 09:06:26.000000', NULL, 1),
(2149511, 292540, 48298, '<td valign="top">Good find and composition.  Color seems a bit over-saturated...the green is a little too green.</td>', 'Good find and composition.  Color seems a bit over-saturated...the green is a little too green.', '2006-02-14 09:07:48.000000', NULL, 1),
(2149515, 292186, 48298, '<td valign="top">I favor outdoor, natural shots like this.  Nice composition and real color...I like the leaves, too.</td>', 'I favor outdoor, natural shots like this.  Nice composition and real color...I like the leaves, too.', '2006-02-14 09:09:01.000000', NULL, 1),
(2149517, 291565, 48298, '<td valign="top">Awesome find for this Challenge, and I love outdoor shots.  10.  Good luck.</td>', 'Awesome find for this Challenge, and I love outdoor shots.  10.  Good luck.', '2006-02-14 09:10:12.000000', NULL, 1),
(2149519, 291915, 48298, '<td valign="top">I like the color, but I''m afraid the voters are going to tell you they don''t see something obviously "broken".  I''ll mark it higher, because I believe you.  :)</td>', 'I like the color, but I''m afraid the voters are going to tell you they don''t see something obviously "broken".  I''ll mark it higher, because I believe you.  :)', '2006-02-14 09:11:28.000000', NULL, 1),
(2149526, 291805, 48298, '<td valign="top">I''m marking down every broken egg image in this Challenge on principle.  It was broken specifically for the Challenge and not "already broken", and I think it isn''t fair to people who took the time to go out looking for something broken.  Good shot, but cliche.</td>', 'I''m marking down every broken egg image in this Challenge on principle.  It was broken specifically for the Challenge and not "already broken", and I think it isn''t fair to people who took the time to go out looking for something broken.  Good shot, but cliche.', '2006-02-14 09:16:42.000000', NULL, 1),
(2149530, 292026, 48298, '<td valign="top">C''mon already.  How many broken eggs are in this Challenge?  I''m marking this down on principle...as broken just for this Challenge and not something "already broken".  Cliche.</td>', 'C''mon already.  How many broken eggs are in this Challenge?  I''m marking this down on principle...as broken just for this Challenge and not something "already broken".  Cliche.', '2006-02-14 09:19:23.000000', NULL, 1),
(2149541, 292882, 48298, '<td valign="top">This stands out as unique, but could be a little sharper.  Good comp and original.  Taking off a little for sharpness, but not much.</td>', 'This stands out as unique, but could be a little sharper.  Good comp and original.  Taking off a little for sharpness, but not much.', '2006-02-14 09:21:23.000000', NULL, 1),
(2149545, 291817, 48298, '<td valign="top">Better than your average egg shot, but on principle I am marking down every egg image in this Challenge, as something broken just for the Challenge and not "already broken".  Cliche.</td>', 'Better than your average egg shot, but on principle I am marking down every egg image in this Challenge, as something broken just for the Challenge and not "already broken".  Cliche.', '2006-02-14 09:24:30.000000', NULL, 1),
(2149549, 292813, 48298, '<td valign="top">Probably not an easy shot, but don''t get the purple on the falling egg, and on principle I am marking down every egg image in this Challenge as something just broken and not "already broken".  Cliche...although yours is less cliche than most.</td>', 'Probably not an easy shot, but don''t get the purple on the falling egg, and on principle I am marking down every egg image in this Challenge as something just broken and not "already broken".  Cliche...although yours is less cliche than most.', '2006-02-14 09:26:28.000000', NULL, 1),
(2149551, 292552, 48298, '<td valign="top">FINALLY!  An egg shot that wasn''t broken indoors in a studio just for the Challenge!  I''m thrilled.  Great find and I hope it beats the cliche shots!!!  10 for you.</td>', 'FINALLY!  An egg shot that wasn''t broken indoors in a studio just for the Challenge!  I''m thrilled.  Great find and I hope it beats the cliche shots!!!  10 for you.', '2006-02-14 09:29:05.000000', NULL, 1),
(2149556, 291458, 48298, '<td valign="top">LOL - very clever.  BandAids on a broken heart.  Wonderful composition.</td>', 'LOL - very clever.  BandAids on a broken heart.  Wonderful composition.', '2006-02-14 09:30:34.000000', NULL, 1),
(2149565, 292805, 48298, '<td valign="top">Another image that should ribbon!  Very sharp, wonderful DOF, and you put a lot of thought into the perspective and composition, I can tell.  I like the broken glass in the top left, too.  Hope to see this on the front page.</td>', 'Another image that should ribbon!  Very sharp, wonderful DOF, and you put a lot of thought into the perspective and composition, I can tell.  I like the broken glass in the top left, too.  Hope to see this on the front page.', '2006-02-14 09:35:01.000000', NULL, 1),
(2149569, 292191, 48298, '<td valign="top">This is interesting.  I like all the texture and detail.  Simple but striking...well done.</td>', 'This is interesting.  I like all the texture and detail.  Simple but striking...well done.', '2006-02-14 09:36:46.000000', NULL, 1),
(2149572, 291899, 48298, '<td valign="top">You pulled this off very well, with the darkness behind the shattered panes.  Effective composition.  Good job.</td>', 'You pulled this off very well, with the darkness behind the shattered panes.  Effective composition.  Good job.', '2006-02-14 09:38:36.000000', NULL, 1),
(2149574, 292045, 48298, '<td valign="top">YIKES!  This is one of my favorites.  Beautiful and frightening image.  Perfect, I think.  10.  I really hope you ribbon, and if a cliche studio egg shot beats you, I protest.  ;)<br/>(I''m adding this my Favorites list!)</td>', 'YIKES!  This is one of my favorites.  Beautiful and frightening image.  Perfect, I think.  10.  I really hope you ribbon, and if a cliche studio egg shot beats you, I protest.  ;)(I''m adding this my Favorites list!)', '2006-02-14 09:40:30.000000', NULL, 1),
(2149580, 289955, 48298, '<td valign="top">I usually just leave kind comments, but all the egg shots in this Challenge have really gotten on my nerves.  On principle, I am marking each down as something JUST broken, and not "already broken".  So cliche, no matter how well-shot.  Please go outside and look around you.</td>', 'I usually just leave kind comments, but all the egg shots in this Challenge have really gotten on my nerves.  On principle, I am marking each down as something JUST broken, and not "already broken".  So cliche, no matter how well-shot.  Please go outside and look around you.', '2006-02-14 09:44:32.000000', NULL, 1),
(2149595, 291897, 48298, '<td valign="top">Well, I think it is very nice, and I''ll take your broken branch over a broken egg any day.  :)</td>', 'Well, I think it is very nice, and I''ll take your broken branch over a broken egg any day.  :)', '2006-02-14 09:53:13.000000', NULL, 1),
(2149615, 292047, 52673, '<td valign="top">Nice idea</td>', 'Nice idea', '2006-02-14 10:10:18.000000', NULL, 1),
(2149617, 290289, 52673, '<td valign="top">I like this a lot - well suited to mono conversion and nicely composed</td>', 'I like this a lot - well suited to mono conversion and nicely composed', '2006-02-14 10:11:46.000000', NULL, 1),
(2149626, 292830, 34399, '<td valign="top">excellent, both photo and caption</td>', 'excellent, both photo and caption', '2006-02-14 10:20:05.000000', NULL, 1),
