(2151352, 290159, 40718, '<td valign="top">Ya, I figured this was yours after that cryptic remark in the scores!  Great shot!  I wouldn''t have been disappointed at all if it had blued over mine...</td>', 'Ya, I figured this was yours after that cryptic remark in the scores!  Great shot!  I wouldn''t have been disappointed at all if it had blued over mine...', '2006-02-15 00:16:18.000000', NULL, 0),
(2151354, 292151, 17851, '<td valign="top">congrats!</td>', 'congrats!', '2006-02-15 00:16:25.000000', NULL, 0),
(2151357, 292151, 5792, '<td valign="top">Congratulations... nice shot of the Peter Iredale, Oregon''s most famous and enduring shipwreck! Reminds me of home.</td>', 'Congratulations... nice shot of the Peter Iredale, Oregon''s most famous and enduring shipwreck! Reminds me of home.', '2006-02-15 00:16:54.000000', NULL, 0),
(2151373, 291258, 33552, '<td valign="top">Narrow DOF would bee more effective if the subject was a little more obvious. LOL. I love the idea but it took me a while to figure it out. I''ve found that timing is ... almost.. everything in insect macro. Great color but the DOF issue draws my attention to the leaves and stems rather than the bee which resides in the OOF foreground.</td>', 'Narrow DOF would bee more effective if the subject was a little more obvious. LOL. I love the idea but it took me a while to figure it out. I''ve found that timing is ... almost.. everything in insect macro. Great color but the DOF issue draws my attention to the leaves and stems rather than the bee which resides in the OOF foreground.', '2006-02-15 00:18:54.000000', NULL, 0),
(2151387, 292830, 47096, '<td valign="top">Congrats on your fourth place. This is great! I see that mischevious expression on my cats'' faces a lot too. :)</td>', 'Congrats on your fourth place. This is great! I see that mischevious expression on my cats'' faces a lot too. :)', '2006-02-15 00:20:59.000000', NULL, 0),
